def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[+\-*/(),:=<>]")
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "u-": 4,
        ":": 5,
    }
    values = {}
    active = set()

    def parse(text):
        tokens = token_pattern.findall(text)
        operands = []
        operators = []
        expecting_operand = True
        i = 0

        def apply_operator():
            op = operators.pop()
            if op == "u-":
                operands.append(("unary", operands.pop()))
            else:
                right = operands.pop()
                left = operands.pop()
                operands.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                operands.append(("number", int(token)))
                expecting_operand = False
            elif token[0].isalpha():
                if i + 1 < len(tokens) and tokens[i + 1] == "(":
                    operators.append(["(", token, 0])
                    i += 1
                    expecting_operand = True
                else:
                    operands.append(("cell", token))
                    expecting_operand = False
            elif token == "(":
                operators.append(["(", None, 0])
                expecting_operand = True
            elif token == ",":
                while not isinstance(operators[-1], list):
                    apply_operator()
                operators[-1][2] += 1
                expecting_operand = True
            elif token == ")":
                while not isinstance(operators[-1], list):
                    apply_operator()
                _, function, commas = operators.pop()
                if function is not None:
                    count = commas + 1
                    args = operands[-count:]
                    del operands[-count:]
                    operands.append(("function", function, args))
                expecting_operand = False
            else:
                op = "u-" if token == "-" and expecting_operand else token
                while operators and not isinstance(operators[-1], list):
                    top = operators[-1]
                    if precedence[top] > precedence[op] or (
                        precedence[top] == precedence[op] and op != "u-"
                    ):
                        apply_operator()
                    else:
                        break
                operators.append(op)
                expecting_operand = True
            i += 1

        while operators:
            apply_operator()
        return operands[0]

    def function_items(args):
        for arg in args:
            if arg[0] == "binary" and arg[1] == ":":
                first = arg[2][1]
                last = arg[3][1]
                left = min(ord(first[0]), ord(last[0]))
                right = max(ord(first[0]), ord(last[0]))
                top = min(int(first[1:]), int(last[1:]))
                bottom = max(int(first[1:]), int(last[1:]))
                for row in range(top, bottom + 1):
                    for column in range(left, right + 1):
                        name = chr(column) + str(row)
                        if name in cells:
                            yield ("cell", name)
            else:
                yield arg

    def evaluate(start):
        tasks = [("cell", start)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name not in cells:
                    results.append(0)
                elif name in values:
                    results.append(values[name])
                elif name in active:
                    results.append("#CYCLE!")
                else:
                    active.add(name)
                    content = cells[name]
                    tasks.append(("finish", name))
                    if content.startswith("="):
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        results.append(int(content))

            elif kind == "finish":
                name = task[1]
                values[name] = results[-1]
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]
                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "cell":
                    tasks.append(("cell", node[1]))
                elif node_kind == "unary":
                    tasks.append(("unary",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                else:
                    function, args = node[1], node[2]
                    if function == "IF":
                        tasks.append(("if", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        tasks.append(
                            ("function_next", function, iter(function_items(args)), None)
                        )

            elif kind == "unary":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                right = results.pop()
                op, left = task[1], task[2]
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(left == right)
                elif op == "<>":
                    results.append(left != right)
                elif op == "<":
                    results.append(left < right)
                elif op == "<=":
                    results.append(left <= right)
                elif op == ">":
                    results.append(left > right)
                else:
                    results.append(left >= right)

            elif kind == "if":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "function_next":
                function, items, accumulated = task[1:]
                item = next(items, None)
                if item is None:
                    results.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append(("function_value", function, items, accumulated))
                    tasks.append(("eval", item))

            else:  # function_value
                function, items, accumulated = task[1:]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if accumulated is None:
                        accumulated = value
                    elif function == "SUM":
                        accumulated += value
                    elif function == "MIN":
                        accumulated = min(accumulated, value)
                    else:
                        accumulated = max(accumulated, value)
                    tasks.append(("function_next", function, items, accumulated))

        return results.pop()

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
